-- MTH 121 (Elementary Mathematics II, UNN) practice questions for the CBT feature.
-- Source: real worked calculus questions supplied by the user (functions, limits,
-- continuity, differentiation, integration), with math notation converted to
-- inline LaTeX ($...$-delimited, per lib/core/widgets/math_text.dart's
-- convention) so it renders as proper mathematical typesetting in the app
-- instead of raw ASCII. One question was dropped: the definite integral of
-- 1/[(x-1)(x+2)] from 0 to 1 has a singularity at x=1 (the upper bound), so
-- it diverges and none of the supplied answer choices are mathematically
-- valid.
--
-- cbt_questions has no course_code column, so the MTH 121 link lives in
-- subject_name. is_general = false and faculty is pinned to 'Faculty of
-- Physical Sciences' so only students in that faculty see this paper —
-- it was initially marked general-studies (visible to everyone) and that
-- let students outside Physical Sciences, e.g. Public Administration, see
-- a paper that isn't in their own course outline.

delete from public.cbt_questions where subject_id = 'mth-121-calculus';

insert into public.cbt_questions
  (subject_id, subject_name, institution, faculty, department, level,
