  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', 'Evaluate $\lim_{x \to 0} [(1-cos x)/x]$.', '["$1$", "$0$", "does not exist", "$1/2$"]'::jsonb, 1, 'Using $\lim_{x \to 0}$ $(cos x - 1)/x = 0$, this limit equals 0.', 'Limits of Trigonometric Functions', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', 'Evaluate $\lim_{x \to 0} [x \cdot \sin(1/x)]$ using the Sandwich Theorem.', '["$0$", "$1$", "does not exist", "$\\infty$"]'::jsonb, 0, 'Since -|x|$\leq x$ sin(1/x) ≤ |x| and both bounds go to 0, the Sandwich Theorem gives limit 0.', 'Some Theorems on Limits', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', 'For $f(x) = (x^2-25)/(x-5)$ if $x \neq 5$, and $f(5)$$=10$, is f continuous at x=5?', '["No — removable discontinuity", "No — jump discontinuity", "No — essential discontinuity", "Yes — f is continuous at x=5"]'::jsonb, 3, '(x²-25)/(x-5) simplifies to x+5 for $x \neq 5$, so $\lim_{x \to 5}$  $f(x) = 10$, which equals the given $f(5)$$=10$. Since the limit exists and equals $f(5)$, f is continuous at x=5.', 'Continuous Functions', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', 'For $f(x) = (x^2-25)/(x-5)$ if $x \neq 5$, and $f(5)$$=7$, is f continuous at x=5?', '["No — essential discontinuity", "Yes — f is continuous at x=5", "No — removable discontinuity", "No — jump discontinuity"]'::jsonb, 2, '(x²-25)/(x-5) simplifies to x+5, so $\lim_{x \to 5}$  $f(x) = 10$, but $f(5)$$=7 \neq 10$. Since the limit exists but does not equal $f(5)$, the discontinuity is removable.', 'Types of Discontinuities', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', 'Find the derivative of $f(x) = x^5$.', '["$5x^5$", "$5x^4$", "$20x^3$", "$x^5$"]'::jsonb, 1, 'Applying the power rule term by term: $\dfrac{d}{dx}[x^5]$ $= 5 \cdot x^4$.', 'Derivative of the Power Function', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', 'Find the derivative of $f(x) = 3x^4$.', '["$12x^3$", "$3x^4$", "$12x^4$", "$36x^2$"]'::jsonb, 0, 'Applying the power rule term by term: $\dfrac{d}{dx}[3x^4]$ $= 12 \cdot x^3$.', 'Derivative of the Power Function', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', 'Find the derivative of $f(x) = 7x^3 - 2x^2 + x$.', '["$7x^3 - 2x^2 + x$", "$21x^3 - 4x^2 + x$", "$42x - 4$", "$21x^2 - 4x + 1$"]'::jsonb, 3, 'Applying the power rule term by term: $\dfrac{d}{dx}[7x^3 - 2x^2 + x]$ $= 21 \cdot x^2 - 4 \cdot x + 1$.', 'Derivative of the Power Function', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', 'Find the derivative of $f(x) = x^6 - 4x$.', '["$30x^4$", "$6x^5 - 4$", "$x^6 - 4x$", "$6x^6 - 4x$"]'::jsonb, 1, 'Applying the power rule term by term: $\dfrac{d}{dx}[x^6 - 4x]$ $= 6 \cdot x^5 - 4$.', 'Derivative of the Power Function', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', 'Find the derivative of $f(x) = 2x^7 + 5$.', '["$14x^6$", "$14x^7$", "$84x^5$", "$2x^7 + 5$"]'::jsonb, 0, 'Applying the power rule term by term: $\dfrac{d}{dx}[2x^7 + 5]$ $= 14 \cdot x^6$.', 'Derivative of the Power Function', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', 'Find the derivative of $f(x) = x^2/2 - 3x$.', '["$1$", "$x - 3$", "$x^2/2 - 3x$", "$x^2 - 3x$"]'::jsonb, 1, 'Applying the power rule term by term: $\dfrac{d}{dx}[x^2/2 - 3x]$ $= x - 3$.', 'Derivative of the Power Function', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', 'Find the derivative of $f(x) = \sin(x)$.', '["$\\cos(x) + 1$", "$\\cos(x)$", "$\\sin(x)$", "$-\\cos(x)$"]'::jsonb, 1, 'Using the standard trigonometric derivative rules, $\dfrac{d}{dx}[\sin(x)]$ $= \cos(x)$.', 'Derivatives of Trigonometric Functions', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', 'Find the derivative of $f(x) = \cos(x)$.', '["$\\sin(x)$", "$-\\sin(x)$", "$\\cos(x)$", "$1 - \\sin(x)$"]'::jsonb, 1, 'Using the standard trigonometric derivative rules, $\dfrac{d}{dx}[\cos(x)]$ $= -\sin(x)$.', 'Derivatives of Trigonometric Functions', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', 'Find the derivative of $f(x) = \tan(x)$.', '["$-1/\\cos(x)^2$", "$\\tan(x)$", "$\\cos(x)$", "$\\cos(x)^{-2}$"]'::jsonb, 3, 'Using the standard trigonometric derivative rules, $\dfrac{d}{dx}[\tan(x)]$ $= \tan(x)^2 + 1$.', 'Derivatives of Trigonometric Functions', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', 'Find the derivative of $f(x) = 3 \sin(x)$.', '["$\\cos(x)$", "$-3 \\cos(x)$", "$3 \\cos(x)$", "$3 \\sin(x)$"]'::jsonb, 2, 'Using the standard trigonometric derivative rules, $\dfrac{d}{dx}[3 \sin(x)]$ $= 3 \cdot \cos(x)$.', 'Derivatives of Trigonometric Functions', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', 'Find the derivative of $f(x) = \sin(x) + \cos(x)$.', '["$-\\sin(x) + \\cos(x)$", "$\\sin(x) - \\cos(x)$", "$\\sin(x) + \\cos(x)$", "$\\cos(x)$"]'::jsonb, 0, 'Using the standard trigonometric derivative rules, $\dfrac{d}{dx}[\sin(x) + \cos(x)]$ $= -\sin(x) + \cos(x)$.', 'Derivatives of Trigonometric Functions', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', 'Using the Product Rule, find the derivative of $f(x) = x^2 \cdot \sin(x)$.', '["$x(x \\cos(x) + 2 \\sin(x))$", "$x^2 \\cos(x)$", "$2x \\cos(x)$", "$2x \\sin(x)$"]'::jsonb, 0, 'Product Rule: (uv)'' = u''v + uv''. Here u''=2x, $v''=\cos(x)$, giving $f''(x) = x^2 \cdot \cos(x) + 2 \cdot x \cdot \sin(x)$.', 'Rules of Differentiation', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', 'Using the Product Rule, find the derivative of $f(x) = x \cdot \cos(x)$.', '["$-x \\sin(x)$", "$-x \\sin(x) + \\cos(x)$", "$\\cos(x)$", "$-\\sin(x)$"]'::jsonb, 1, 'Product Rule: (uv)'' = u''v + uv''. Here u''=1, $v''=-\sin(x)$, giving $f''(x) = -x \cdot \sin(x) + \cos(x)$.', 'Rules of Differentiation', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', 'Using the Product Rule, find the derivative of $f(x) = x^2 \cdot x + 1$.', '["$x^2$", "$2x$", "$2x^2 + 2x$", "$3x^2 + 2x$"]'::jsonb, 3, 'Product Rule: (uv)'' = u''v + uv''. Here u''=2x, $v''=1$, giving $f''(x) = 3 \cdot x^2 + 2 \cdot x$.', 'Rules of Differentiation', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', 'Using the Product Rule, find the derivative of $f(x) = \sin(x) \cdot \cos(x)$.', '["$\\cos(2x)$", "$-\\sin(x)^2$", "$\\cos(x)^2$", "$-\\sin(2x)/2$"]'::jsonb, 0, 'Product Rule: (uv)'' = u''v + uv''. Here u''=cos(x), $v''=-\sin(x)$, giving $f''(x) = -\sin(x)^2 + \cos(x)^2$.', 'Rules of Differentiation', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', 'Using the Quotient Rule, find the derivative of $f(x) = (x)/(x + 1)$.', '["$1/(x^2 + 2x + 1)$", "$1/(x + 1)$", "$1$", "$2x/(x^2 + 2x + 1) + 1/(x^2 + 2x + 1)$"]'::jsonb, 0, 'Quotient Rule: (u/v)'' = (u''v - uv'')/v². Here u''=1, $v''=1$, giving $f''(x) = (x + 1)^{-2}$.', 'Rules of Differentiation', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', 'Using the Quotient Rule, find the derivative of $f(x) = (x^2)/(x - 2)$.', '["$x^2/(x^2 - 4x + 4) - 4x/(x^2 - 4x + 4)$", "$2x$", "$2x/(x - 2)$", "$3x^2/(x^2 - 4x + 4) - 4x/(x^2 - 4x + 4)$"]'::jsonb, 0, 'Quotient Rule: (u/v)'' = (u''v - uv'')/v². Here u''=2x, $v''=1$, giving $f''(x) = x \cdot (x - 4)/(x^2 - 4 \cdot x + 4)$.', 'Rules of Differentiation', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', 'Using the Quotient Rule, find the derivative of $f(x) = (\sin(x))/(x)$.', '["$(x \\cos(x) + \\sin(x))/x^2$", "$(x \\cos(x) - \\sin(x))/x^2$", "$\\cos(x)/x$", "$\\cos(x)$"]'::jsonb, 1, 'Quotient Rule: (u/v)'' = (u''v - uv'')/v². Here u''=cos(x), $v''=1$, giving $f''(x) = (x \cdot \cos(x) - \sin(x))/x^2$.', 'Rules of Differentiation', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', 'Using the Quotient Rule, find the derivative of $f(x) = (2x + 1)/(x^2 + 1)$.', '["$1/x$", "$-2x^2/(x^4 + 2x^2 + 1) - 2x/(x^4 + 2x^2 + 1) + 2/(x^4 + 2x^2 + 1)$", "$2/(x^2 + 1)$", "$6x^2/(x^4 + 2x^2 + 1) + 2x/(x^4 + 2x^2 + 1) + 2/(x^4 + 2x^2 + 1)$"]'::jsonb, 1, 'Quotient Rule: (u/v)'' = (u''v - uv'')/v². Here u''=2, $v''=2 \cdot x$, giving $f''(x) = 2 \cdot (-x^2 - x + 1)/(x^4 + 2 \cdot x^2 + 1)$.', 'Rules of Differentiation', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', 'Using the Chain Rule, find the derivative of $f(x) = (x^2 + 1)^3$.', '["$3x^4 + 6x^2 + 3$", "$6x^5 + 12x^3 + 6x$", "$8x^3$", "$6x^7 + 18x^5 + 18x^3 + 6x$"]'::jsonb, 1, 'Chain Rule: with u=x^2 + 1, $D[u^3]$ $= 3u^2 \cdot Du = 3(x^2 + 1)^2 \cdot (2 \cdot x) = 6 \cdot x^5 + 12 \cdot x^3 + 6 \cdot x$.', 'The Chain Rule', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', 'Using the Chain Rule, find the derivative of $f(x) = (2x - 5)^4$.', '["$64x^3 - 480x^2 + 1200x - 1000$", "$16$", "$128x^4 - 1280x^3 + 4800x^2 - 8000x + 5000$", "$32x^3 - 240x^2 + 600x - 500$"]'::jsonb, 0, 'Chain Rule: with u=2x - 5, $D[u^4]$ $= 4u^3 \cdot Du = 4(2x - 5)^3 \cdot (2) = 64 \cdot x^3 - 480 \cdot x^2 + 1200 \cdot x - 1000$.', 'The Chain Rule', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', 'Using the Chain Rule, find the derivative of $f(x) = (x^3 - 2x)^2$.', '["$2x^3 - 4x$", "$9x^4 - 12x^2 + 4$", "$6x^5 - 16x^3 + 8x$", "$6x^8 - 28x^6 + 40x^4 - 16x^2$"]'::jsonb, 2, 'Chain Rule: with u=x^3 - 2x, $D[u^2]$ $= 2u^1 \cdot Du = 2(x^3 - 2x)^1 \cdot (3 \cdot x^2 - 2) = 6 \cdot x^5 - 16 \cdot x^3 + 8 \cdot x$.', 'The Chain Rule', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', 'Find the derivative of $f(x) = \sin(2x + 3)$.', '["$2 \\cos(2x + 3)$", "$\\cos(2x + 3)$", "$-2 \\cos(2x + 3)$", "$\\sin(2)$"]'::jsonb, 0, 'By the Chain Rule, $D[\sin(u)]$ $= \cos(u) \cdot Du$, with u=2x + 3, $Du=2$, giving $f''(x) = 2 \cdot \cos(2 \cdot x + 3)$.', 'The Chain Rule', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', 'Find the derivative of $f(x) = \sin(x^2)$.', '["$-2x \\cos(x^2)$", "$\\sin(2x)$", "$\\cos(x^2)$", "$2x \\cos(x^2)$"]'::jsonb, 3, 'By the Chain Rule, $D[\sin(u)]$ $= \cos(u) \cdot Du$, with u=x^2, $Du=2 \cdot x$, giving $f''(x) = 2 \cdot x \cdot \cos(x^2)$.', 'The Chain Rule', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', 'Find the derivative of $f(x) = \sin(3x - 1)$.', '["$\\cos(3x - 1)$", "$-3 \\cos(3x - 1)$", "$3 \\cos(3x - 1)$", "$\\sin(3)$"]'::jsonb, 2, 'By the Chain Rule, $D[\sin(u)]$ $= \cos(u) \cdot Du$, with u=3x - 1, $Du=3$, giving $f''(x) = 3 \cdot \cos(3 \cdot x - 1)$.', 'The Chain Rule', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', 'Find the slope of the tangent line to $y = x^2 - 4x + 3 at x = 1$.', '["$-2$", "$-1$", "$0$", "$2$"]'::jsonb, 0, 'The slope is $f''(1)$ where $f''(x) = 2 \cdot x - 4$, so $f''(1)$ $= -2$.', 'The Derivative', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', 'Find the slope of the tangent line to $y = x^3 - 3x at x = 2$.', '["$2$", "$11$", "$-9$", "$9$"]'::jsonb, 3, 'The slope is $f''(2)$ where $f''(x) = 3 \cdot x^2 - 3$, so $f''(2)$ $= 9$.', 'The Derivative', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', 'Find the slope of the tangent line to $y = 2x^2 + 1 at x = -1$.', '["$-4$", "$3$", "$-2$", "$4$"]'::jsonb, 0, 'The slope is $f''(-1)$ where $f''(x) = 4 \cdot x$, so $f''(-1)$ $= -4$.', 'The Derivative', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', 'Find the slope of the tangent line to $y = x^2 at x = 3$.', '["$9$", "$6$", "$-6$", "$8$"]'::jsonb, 1, 'The slope is $f''(3)$ where $f''(x) = 2 \cdot x$, so $f''(3)$ $= 6$.', 'The Derivative', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', 'If x² + y² = 25, find dy/dx at the point (3,4).', '["$4/3$", "$-4/3$", "$3/4$", "$-3/4$"]'::jsonb, 3, 'Differentiating implicitly: 2x + 2y(dy/dx) = 0, so $dy/dx = -x/y$. At (3,4): $dy/dx = -3/4$.', 'Implicit Differentiation', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', 'If x³ + y³ = 9, find dy/dx at the point (1,2).', '["$1/4$", "$-4$", "$4$", "$-1/4$"]'::jsonb, 3, 'Differentiating implicitly: 3x² + 3y²(dy/dx) = 0, so $dy/dx = -x^2/y^2$. At (1,2): $dy/dx = -1/4$.', 'Implicit Differentiation', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', 'Find the critical point(s) of $f(x) = x^3 - 3x + 1$.', '["$0$", "$-1, 1$", "no critical points", "$0, 2$"]'::jsonb, 1, '$f''(x) = 3 \cdot x^2 - 3$. Setting $f''(x) = 0 and solving gives x = -1$, $1$.', 'Maxima and Minima', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', 'Find the critical point(s) of $f(x) = x^2 - 6x + 5$.', '["no critical points", "$3$", "$4$", "$2$"]'::jsonb, 1, '$f''(x) = 2 \cdot x - 6$. Setting $f''(x) = 0 and solving gives x = 3$.', 'Maxima and Minima', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', 'Find the critical point(s) of $f(x) = 2x^3 - 3x^2 - 12x + 4$.', '["$0, 3$", "$0$", "no critical points", "$-1, 2$"]'::jsonb, 3, '$f''(x) = 6 \cdot x^2 - 6 \cdot x - 12$. Setting $f''(x) = 0 and solving gives x = -1$, $2$.', 'Maxima and Minima', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', 'Find the critical point(s) of $f(x) = x^3 - 12x$.', '["$-2, 2$", "$-1, 3$", "$0$", "no critical points"]'::jsonb, 0, '$f''(x) = 3 \cdot x^2 - 12$. Setting $f''(x) = 0 and solving gives x = -2$, $2$.', 'Maxima and Minima', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', 'At the critical point x = 1 of $f(x) = x^3 - 3x$, the Second Derivative Test shows this is a:', '["point of inflection", "relative maximum", "not a critical point", "relative minimum"]'::jsonb, 3, '$f''''(x) = 6 \cdot x$, so $f''''(1)$ $= 6$, which is positive, indicating a relative minimum.', 'The Second Derivative Test for Extremum', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', 'At the critical point x = -1 of $f(x) = x^3 - 3x$, the Second Derivative Test shows this is a:', '["relative minimum", "not a critical point", "relative maximum", "point of inflection"]'::jsonb, 2, '$f''''(x) = 6 \cdot x$, so $f''''(-1)$ $= -6$, which is negative, indicating a relative maximum.', 'The Second Derivative Test for Extremum', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', 'At the critical point x = 2 of $f(x) = x^2 - 4x + 7$, the Second Derivative Test shows this is a:', '["relative maximum", "not a critical point", "relative minimum", "point of inflection"]'::jsonb, 2, '$f''''(x) = 2$, so $f''''(2)$ $= 2$, which is positive, indicating a relative minimum.', 'The Second Derivative Test for Extremum', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', 'At the critical point x = 3 of $f(x) = -x^2 + 6x - 5$, the Second Derivative Test shows this is a:', '["not a critical point", "relative maximum", "relative minimum", "point of inflection"]'::jsonb, 1, '$f''''(x) = -2$, so $f''''(3)$ $= -2$, which is negative, indicating a relative maximum.', 'The Second Derivative Test for Extremum', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', 'For $f(x) = x^2 - 4x + 3$, on which interval is f increasing?', '["$(2, \\infty)$", "$(-\\infty, \\infty)$", "$(0, 2)$", "$(-\\infty, 2)$"]'::jsonb, 0, '$f''(x) = 2x - 4$, which is positive when $x > 2$, so f is increasing on (2, ∞).', 'Monotonicity of a Function', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', 'For $f(x) = x^3 - 3x$, on which interval is f decreasing?', '["$(-\\infty, \\infty)$", "$(-\\infty,-1)$", "$(-1, 1)$", "$(1, \\infty)$"]'::jsonb, 2, '$f''(x) = 3x^2-3 = 3(x-1)(x+1)$, which is negative for $-1<x<1$, so f is decreasing on (-1,1).', 'Monotonicity of a Function', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', 'Find the equation of the tangent line to $y = x^2 at x = -1$.', '["$y = -2x + 1$", "$y = -2x - 1$", "$y = 1x - 2$", "$y = 2x - 1$"]'::jsonb, 1, '$f(-1)$$=1$, $f''(-1)$$=-2$. Using y - f(a) = f''(a)(x-a): $y = -2(x--1) + 1 = y = -2x - 1$.', 'Tangents and Normals', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', 'Find the equation of the tangent line to $y = x^2 - 3x + 2 at x = 1$.', '["$y = 0x - 1$", "$y = 1x + 1$", "$y = -1x + 1$", "$y = -1x$"]'::jsonb, 2, '$f(1)$$=0$, $f''(1)$$=-1$. Using y - f(a) = f''(a)(x-a): $y = -1(x-1) + 0 = y = -1x + 1$.', 'Tangents and Normals', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', 'Find the equation of the tangent line to $y = x^3 at x = 1$.', '["$y = -3x - 2$", "$y = 3x + 1$", "$y = 3x - 2$", "$y = 1x + 3$"]'::jsonb, 2, '$f(1)$$=1$, $f''(1)$$=3$. Using y - f(a) = f''(a)(x-a): $y = 3(x-1) + 1 = y = 3x - 2$.', 'Tangents and Normals', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', 'Find the equation of the tangent line to $y = x^2 at x = 3$.', '["$y = -6x - 9$", "$y = 9x + 6$", "$y = 6x + 9$", "$y = 6x - 9$"]'::jsonb, 3, '$f(3)$$=9$, $f''(3)$$=6$. Using y - f(a) = f''(a)(x-a): $y = 6(x-3) + 9 = y = 6x - 9$.', 'Tangents and Normals', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', 'Use L''Hopital''s Rule to evaluate $\lim_{x \to 0} [\sin(x)/x]$.', '["$1$", "does not exist", "$\\infty$", "$0$"]'::jsonb, 0, 'This is a 0/0 form. Differentiating numerator and denominator separately and taking the limit gives 1.', 'Indeterminate Forms and L''Hopital''s Rule', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', 'Use L''Hopital''s Rule to evaluate $\lim_{x \to 1} [(x^2 - 1)/(x - 1)]$.', '["$2$", "$\\infty$", "$0$", "does not exist"]'::jsonb, 0, 'This is a 0/0 form. Differentiating numerator and denominator separately and taking the limit gives 2.', 'Indeterminate Forms and L''Hopital''s Rule', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', 'Use L''Hopital''s Rule to evaluate $\lim_{x \to 0} [(1 - \cos(x))/x^2]$.', '["does not exist", "$\\infty$", "$1/2$", "$0$"]'::jsonb, 2, 'This is a 0/0 form. Differentiating numerator and denominator separately and taking the limit gives 1/2.', 'Indeterminate Forms and L''Hopital''s Rule', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', 'Use L''Hopital''s Rule to evaluate $\lim_{x \to 2} [(x^2 - 4)/(x - 2)]$.', '["$0$", "$\\infty$", "$4$", "does not exist"]'::jsonb, 2, 'This is a 0/0 form. Differentiating numerator and denominator separately and taking the limit gives 4.', 'Indeterminate Forms and L''Hopital''s Rule', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', 'For $f(x) = x^3 - 6x^2 + 9x$, find the x-coordinate of the point of inflection.', '["$-2$", "$3$", "$0$", "$2$"]'::jsonb, 3, '$f''''(x) = 6x - 12$. Setting $f''''(x) = 0 gives x=2$, where concavity changes.', 'Concavity and Points of Inflection', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', 'For $f(x) = x^4 - 2x^2$, on which interval is f concave up?', '["$x < -1/$√3 or $x > 1/$√3", "$-1/\\sqrt{3} < x < 1/\\sqrt{3}$", "all real x", "no interval"]'::jsonb, 0, '$f''''(x) = 12x^2 - 4$. Setting f''''(x) > 0 gives x² > 1/3, i.e. $x < -1/$√3 or $x > 1/$√3.', 'Concavity and Points of Inflection', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', 'Find $\int 3x^2 \, dx$.', '["$x^3 + C$", "$6x + C$", "$3x^2 + C$", "$2x^3 + C$"]'::jsonb, 0, 'Using the power rule for antiderivatives term by term: $\int 3x^2 \, dx$ $= x^3 + C$.', 'Antiderivatives of Some Elementary Functions', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', 'Find $\int 4x^3 - 2x \, dx$.', '["$2x^4 - 2x^2 + C$", "$4x^3 - 2x + C$", "$12x^2 - 2 + C$", "$x^4 - x^2 + C$"]'::jsonb, 3, 'Using the power rule for antiderivatives term by term: $\int 4x^3 - 2x \, dx$ $= x^4 - x^2 + C$.', 'Antiderivatives of Some Elementary Functions', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', 'Find $\int x^4 + 5x^2 \, dx$.', '["$4x^3 + 10x + C$", "$2x^5/5 + 10x^3/3 + C$", "$x^4 + 5x^2 + C$", "$x^5/5 + 5x^3/3 + C$"]'::jsonb, 3, 'Using the power rule for antiderivatives term by term: $\int x^4 + 5x^2 \, dx$ $= x^5/5 + 5x^3/3 + C$.', 'Antiderivatives of Some Elementary Functions', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', 'Find $\int 6x^5 - 3 \, dx$.', '["$6x^5 - 3 + C$", "$x^6 - 3x + C$", "$30x^4 + C$", "$2x^6 - 6x + C$"]'::jsonb, 1, 'Using the power rule for antiderivatives term by term: $\int 6x^5 - 3 \, dx$ $= x^6 - 3x + C$.', 'Antiderivatives of Some Elementary Functions', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', 'Find $\int 2x + 7 \, dx$.', '["$2 + C$", "$x^2 + 7x + C$", "$2x^2 + 14x + C$", "$2x + 7 + C$"]'::jsonb, 1, 'Using the power rule for antiderivatives term by term: $\int 2x + 7 \, dx$ $= x^2 + 7x + C$.', 'Antiderivatives of Some Elementary Functions', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', 'Find $\int \sin(x) \, dx$.', '["$\\sec(x) + C$", "$-\\sin(x) + C$", "$-\\cos(x) + C$", "$\\cos(x) + C$"]'::jsonb, 2, 'Using the standard antiderivative formulas for trigonometric functions: $\int \sin(x) \, dx$ $= -\cos(x) + C$.', 'Antiderivatives of Some Elementary Functions', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', 'Find $\int \cos(x) \, dx$.', '["$\\cos(x) + C$", "$\\sin(x) + C$", "$-\\sin(x) + C$", "$\\sec(x) + C$"]'::jsonb, 1, 'Using the standard antiderivative formulas for trigonometric functions: $\int \cos(x) \, dx$ $= \sin(x) + C$.', 'Antiderivatives of Some Elementary Functions', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', 'Find $\int \sec(x)^2 \, dx$.', '["$\\tan(x) + C$", "$-\\tan(x) + C$", "$\\sec(x)\\tan(x) + C$", "$\\cot(x) + C$"]'::jsonb, 0, 'Using the standard antiderivative formula: $\int sec^2(x) \, dx$ $= \tan(x) + C$.', 'Antiderivatives of Some Elementary Functions', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', 'Find $\int 3 \sin(x) \, dx$.', '["$-3 \\cos(x) + C$", "$\\sec(x) + C$", "$-3 \\sin(x) + C$", "$3 \\cos(x) + C$"]'::jsonb, 0, 'Using the standard antiderivative formulas for trigonometric functions: $\int 3 \sin(x) \, dx$ $= -3 \cos(x) + C$.', 'Antiderivatives of Some Elementary Functions', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', 'Evaluate $\int_{0}^{2} x^2 \, dx$.', '["$5/3$", "$-8/3$", "$8/3$", "$11/3$"]'::jsonb, 2, 'An antiderivative is $F(x) = x^3/3$. By the Fundamental Theorem, the definite integral is F(2) - $F(0) = 8/3 - (0) = 8/3$.', 'Fundamental Theorem of Integral Calculus', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', 'Evaluate $\int_{1}^{4} 3x - 1 \, dx$.', '["$41/2$", "$-39/2$", "$20$", "$39/2$"]'::jsonb, 3, 'An antiderivative is $F(x) = 3x^2/2 - x$. By the Fundamental Theorem, the definite integral is F(4) - $F(1) = 20 - (1/2) = 39/2$.', 'Fundamental Theorem of Integral Calculus', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', 'Evaluate $\int_{0}^{3} x^2 - 4x + 3 \, dx$.', '["$-1$", "$2$", "$0$", "$1$"]'::jsonb, 2, 'An antiderivative is $F(x) = x^3/3 - 2x^2 + 3x$. By the Fundamental Theorem, the definite integral is F(3) - $F(0) = 0 - (0) = 0$.', 'Fundamental Theorem of Integral Calculus', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', 'Evaluate $\int_{-1}^{2} 2x + 1 \, dx$.', '["$7$", "$5$", "$6$", "$-6$"]'::jsonb, 2, 'An antiderivative is $F(x) = x^2 + x$. By the Fundamental Theorem, the definite integral is F(2) - $F(-1) = 6 - (0) = 6$.', 'Fundamental Theorem of Integral Calculus', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', 'Evaluate $\int_{0}^{1} x^3 \, dx$.', '["$-3/4$", "$1/4$", "$-1/4$", "$5/4$"]'::jsonb, 1, 'An antiderivative is $F(x) = x^4/4$. By the Fundamental Theorem, the definite integral is F(1) - $F(0) = 1/4 - (0) = 1/4$.', 'Fundamental Theorem of Integral Calculus', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', 'Evaluate $\int_{-1}^{1} 4 - x^2 \, dx$.', '["$-22/3$", "$22/3$", "$25/3$", "$11/3$"]'::jsonb, 1, 'An antiderivative is $F(x) = -x^3/3 + 4x$. By the Fundamental Theorem, the definite integral is F(1) - $F(-1) = 11/3 - (-11/3) = 22/3$.', 'Fundamental Theorem of Integral Calculus', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', 'Find the area of the region bounded by $y = x^2$, the x-axis, $x=0$, and x=2.', '["$16/3$", "$11/3$", "$-8/3$", "$8/3$"]'::jsonb, 3, 'Area = $\int_{0}^{2} x^2 \, dx$ $= 8/3$.', 'Areas of Plane Regions', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', 'Find the area of the region bounded by $y = 3x$, the x-axis, $x=0$, and x=4.', '["$-24$", "$25$", "$48$", "$24$"]'::jsonb, 3, 'Area = $\int_{0}^{4} 3x \, dx$ $= 24$.', 'Areas of Plane Regions', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', 'Find the area of the region bounded by $y = 4 - x^2$, the x-axis, $x=-2$, and x=2.', '["$32/3$", "$-32/3$", "$35/3$", "$64/3$"]'::jsonb, 0, 'Area = $\int_{-2}^{2} 4 - x^2 \, dx$ $= 32/3$.', 'Areas of Plane Regions', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', 'Find the area of the region bounded by $y = x^3$, the x-axis, $x=0$, and x=2.', '["$8$", "$-4$", "$4$", "$5$"]'::jsonb, 2, 'Area = $\int_{0}^{2} x^3 \, dx$ $= 4$.', 'Areas of Plane Regions', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', 'Find the area of the region bounded by $y = x + 3 and y = x^2 - 1 between x=-1 and x=1$.', '["$6$", "$-22/3$", "$22/3$", "$28/3$"]'::jsonb, 2, 'Area = $\int_{-1}^{1} [(x + 3) - (x^2 - 1)] \, dx$ $=$ $\int_{-1}^{1} -x^2 + x + 4 \, dx$ $= 22/3$.', 'Areas of Plane Regions', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', 'Find the area of the region bounded by $y = 6 - x and y = x^2 between x=-3 and x=2$.', '["$65/2$", "$-125/6$", "$137/6$", "$125/6$"]'::jsonb, 3, 'Area = $\int_{-3}^{2} [(6 - x) - (x^2)] \, dx$ $=$ $\int_{-3}^{2} -x^2 - x + 6 \, dx$ $= 125/6$.', 'Areas of Plane Regions', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', 'Find the area of the region bounded by $y = x + 5 and y = x^2 - 1 between x=-2 and x=3$.', '["$137/6$", "$55/2$", "$-125/6$", "$125/6$"]'::jsonb, 3, 'Area = $\int_{-2}^{3} [(x + 5) - (x^2 - 1)] \, dx$ $=$ $\int_{-2}^{3} -x^2 + x + 6 \, dx$ $= 125/6$.', 'Areas of Plane Regions', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', 'Using the disc method, find the volume of the solid formed by revolving $y = x about the x-axis from x=0 to x=4$.', '["$128\\pi/3$", "$-64\\pi/3$", "$8\\pi$", "$64\\pi/3$"]'::jsonb, 3, '$V = \\pi$$\int_{0}^{4} (x)^2 \, dx$ $= 64 \cdot \pi/3$.', 'The Disc Method', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', 'Using the disc method, find the volume of the solid formed by revolving $y = sqrt{x} about the x-axis from x=0 to x=4$.', '["$16\\pi$", "$8\\pi$", "$16\\pi/3$", "$-8\\pi$"]'::jsonb, 1, '$V = \\pi$$\int_{0}^{4} (sqrt{x})^2 \, dx$ $= 8 \cdot \pi$.', 'The Disc Method', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', 'Using the disc method, find the volume of the solid formed by revolving $y = 2 about the x-axis from x=0 to x=3$.', '["$12\\pi$", "$24\\pi$", "$-12\\pi$", "$6\\pi$"]'::jsonb, 0, '$V = \\pi$$\int_{0}^{3} (2)^2 \, dx$ $= 12 \cdot \pi$.', 'The Disc Method', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', 'Using the disc method, find the volume of the solid formed by revolving $y = x^2 about the x-axis from x=0 to x=1$.', '["$\\pi/3$", "$-\\pi/5$", "$2\\pi/5$", "$\\pi/5$"]'::jsonb, 3, '$V = \\pi$$\int_{0}^{1} (x^2)^2 \, dx$ $= \pi/5$.', 'The Disc Method', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', 'Find the derivative of $f(x) = \ln(3x^2 + 5)$.', '["$-6x/(3x^2 + 5)$", "$1/(3x^2 + 5)$", "$6x/(3x^2 + 5)$", "$6x$"]'::jsonb, 2, 'By the Chain Rule, $D[\ln(u)]$ $= (Du)/u$. With u=3x^2 + 5, $Du=6 \cdot x$, giving $f''(x) = 6x/(3x^2 + 5)$.', 'The Natural Logarithmic Function', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', 'Find the derivative of $f(x) = \ln(\cos(x))$.', '["$1/\\cos(x)$", "$-\\sin(x)$", "$\\tan(x)$", "$-\\tan(x)$"]'::jsonb, 3, 'By the Chain Rule, $D[\ln(u)]$ $= (Du)/u$. With u=cos(x), $Du=-\sin(x)$, giving $f''(x) = -\tan(x)$.', 'The Natural Logarithmic Function', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', 'Find the derivative of $f(x) = \ln(x^3 - 2)$.', '["$1/(x^3 - 2)$", "$3x^2/(x^3 - 2)$", "$-3x^2/(x^3 - 2)$", "$3x^2$"]'::jsonb, 1, 'By the Chain Rule, $D[\ln(u)]$ $= (Du)/u$. With u=x^3 - 2, $Du=3 \cdot x^2$, giving $f''(x) = 3x^2/(x^3 - 2)$.', 'The Natural Logarithmic Function', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', 'Find the derivative of $f(x) = \ln(5x - 1)$.', '["$-5/(5x - 1)$", "$5$", "$5/(5x - 1)$", "$1/(5x - 1)$"]'::jsonb, 2, 'By the Chain Rule, $D[\ln(u)]$ $= (Du)/u$. With u=5x - 1, $Du=5$, giving $f''(x) = 5/(5x - 1)$.', 'The Natural Logarithmic Function', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', 'Find the derivative of $f(x) = e^{4x}$.', '["$-4e^{4x}$", "$4e^{4x}$", "$e^{4x}$", "$4$"]'::jsonb, 1, 'By the Chain Rule, $D[e^u]$ $= e^u \cdot Du$. With u=4x, $Du=4$, giving $f''(x) = 4e^{4x}$.', 'The Exponential Function', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', 'Find the derivative of $f(x) = e^{x^2}$.', '["-2xe^(x^2)", "$2x$", "2xe^(x^2)", "$e^{x^2}$"]'::jsonb, 2, 'By the Chain Rule, $D[e^u]$ $= e^u \cdot Du$. With u=x^2, $Du=2 \cdot x$, giving $f''(x) = 2xe^{x^2}$.', 'The Exponential Function', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', 'Find the derivative of $f(x) = e^{\sin(x)}$.', '["$e^{\\sin(x)}$", "$\\cos(x)$", "$-e^{\\sin(x)}\\cos(x)$", "$e^{\\sin(x)}\\cos(x)$"]'::jsonb, 3, 'By the Chain Rule, $D[e^u]$ $= e^u \cdot Du$. With u=sin(x), $Du=\cos(x)$, giving $f''(x) = e^{\sin(x)}\cos(x)$.', 'The Exponential Function', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', 'Find the derivative of $f(x) = e^{2x - 1}$.', '["$2$", "$2e^{2x - 1}$", "$-2e^{2x - 1}$", "$e^{2x - 1}$"]'::jsonb, 1, 'By the Chain Rule, $D[e^u]$ $= e^u \cdot Du$. With u=2x - 1, $Du=2$, giving $f''(x) = 2e^{2x - 1}$.', 'The Exponential Function', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', 'Find the derivative of $f(x) = a \sin(x)$.', '["$-1/sqrt{1 - x^2}$", "$1/(x^2 + 1)$", "$1/sqrt{1 - x^2}$", "$sqrt{1 - x^2}$"]'::jsonb, 2, 'Using the standard derivative formula for inverse trigonometric functions: $\dfrac{d}{dx}[a \sin(x)]$ $= 1/sqrt{1 - x^2}$.', 'Inverse Trigonometric Functions', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', 'Find the derivative of $f(x) = a \cos(x)$.', '["$1/sqrt{1 - x^2}$", "$sqrt{1 - x^2}$", "$1/(x^2 + 1)$", "$-1/sqrt{1 - x^2}$"]'::jsonb, 3, 'Using the standard derivative formula for inverse trigonometric functions: $\dfrac{d}{dx}[a \cos(x)]$ $= -1/sqrt{1 - x^2}$.', 'Inverse Trigonometric Functions', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', 'Find the derivative of $f(x) = a \tan(x)$.', '["$sqrt{1 - x^2}$", "$1/(x^2 + 1)$", "$-1/(x^2 + 1)$", "$1/sqrt{1 - x^2}$"]'::jsonb, 1, 'Using the standard derivative formula for inverse trigonometric functions: $\dfrac{d}{dx}[a \tan(x)]$ $= 1/(x^2 + 1)$.', 'Inverse Trigonometric Functions', false),
